export const DASHBOARD_HTML = "<title>okfish sync monitor</title>\n<style>\n  :root {\n    --bg: #0b0e13;\n    --surface: #12161d;\n    --surface-2: #171c25;\n    --border: #232a36;\n    --text: #e7ecf3;\n    --text-dim: #8b96a8;\n    --text-faint: #5a6478;\n    --accent: #e8a33d;\n    --accent-dim: #6b5127;\n    --ok: #3fb950;\n    --ok-dim: #1c3a22;\n    --warn: #d29922;\n    --warn-dim: #3d2f10;\n    --crit: #f85149;\n    --crit-dim: #3d1a18;\n  }\n  :root[data-theme=\"light\"] {\n    --bg: #f4f5f7;\n    --surface: #ffffff;\n    --surface-2: #eef0f3;\n    --border: #dde1e7;\n    --text: #171b21;\n    --text-dim: #5c6472;\n    --text-faint: #8891a0;\n    --accent: #b3721c;\n    --accent-dim: #f3e0bd;\n    --ok: #1a7f37;\n    --ok-dim: #dcf5e3;\n    --warn: #9a6700;\n    --warn-dim: #faedcc;\n    --crit: #cf222e;\n    --crit-dim: #fbe0df;\n  }\n  @media (prefers-color-scheme: light) {\n    :root:not([data-theme=\"dark\"]) {\n      --bg: #f4f5f7;\n      --surface: #ffffff;\n      --surface-2: #eef0f3;\n      --border: #dde1e7;\n      --text: #171b21;\n      --text-dim: #5c6472;\n      --text-faint: #8891a0;\n      --accent: #b3721c;\n      --accent-dim: #f3e0bd;\n      --ok: #1a7f37;\n      --ok-dim: #dcf5e3;\n      --warn: #9a6700;\n      --warn-dim: #faedcc;\n      --crit: #cf222e;\n      --crit-dim: #fbe0df;\n    }\n  }\n\n  * { box-sizing: border-box; }\n  html, body {\n    margin: 0;\n    background: var(--bg);\n    color: var(--text);\n    font-family: ui-sans-serif, -apple-system, \"Segoe UI\", Roboto, sans-serif;\n    -webkit-font-smoothing: antialiased;\n  }\n  .mono {\n    font-family: ui-monospace, \"SF Mono\", \"Cascadia Code\", \"JetBrains Mono\", Consolas, monospace;\n    font-variant-numeric: tabular-nums;\n  }\n\n  .wrap {\n    max-width: 980px;\n    margin: 0 auto;\n    padding: 28px 20px 60px;\n  }\n\n  header {\n    display: flex;\n    align-items: baseline;\n    justify-content: space-between;\n    gap: 16px;\n    margin-bottom: 22px;\n    flex-wrap: wrap;\n  }\n  .title-block h1 {\n    font-size: 20px;\n    font-weight: 650;\n    letter-spacing: -0.01em;\n    margin: 0 0 4px;\n  }\n  .title-block .sub {\n    font-size: 13px;\n    color: var(--text-faint);\n  }\n\n  .status-pill {\n    display: inline-flex;\n    align-items: center;\n    gap: 7px;\n    padding: 6px 12px 6px 10px;\n    border-radius: 999px;\n    font-size: 12.5px;\n    font-weight: 600;\n    letter-spacing: 0.01em;\n    border: 1px solid var(--border);\n    background: var(--surface);\n    white-space: nowrap;\n  }\n  .status-dot {\n    width: 8px;\n    height: 8px;\n    border-radius: 50%;\n    background: var(--text-faint);\n    flex-shrink: 0;\n  }\n  .status-pill.running .status-dot {\n    background: var(--accent);\n    box-shadow: 0 0 0 0 var(--accent);\n    animation: pulse 1.6s ease-out infinite;\n  }\n  .status-pill.running { border-color: var(--accent-dim); color: var(--accent); }\n  .status-pill.done .status-dot { background: var(--ok); }\n  .status-pill.done { border-color: var(--ok-dim); color: var(--ok); }\n  .status-pill.error .status-dot { background: var(--crit); }\n  .status-pill.error { border-color: var(--crit-dim); color: var(--crit); }\n\n  @keyframes pulse {\n    0% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--accent) 55%, transparent); }\n    100% { box-shadow: 0 0 0 8px color-mix(in srgb, var(--accent) 0%, transparent); }\n  }\n\n  .meta-row {\n    display: flex;\n    gap: 18px;\n    font-size: 12.5px;\n    color: var(--text-faint);\n    margin-bottom: 24px;\n    flex-wrap: wrap;\n  }\n  .meta-row b { color: var(--text-dim); font-weight: 600; }\n\n  .grid {\n    display: grid;\n    grid-template-columns: repeat(4, 1fr);\n    gap: 12px;\n    margin-bottom: 20px;\n  }\n  @media (max-width: 720px) {\n    .grid { grid-template-columns: repeat(2, 1fr); }\n  }\n\n  .card {\n    background: var(--surface);\n    border: 1px solid var(--border);\n    border-radius: 10px;\n    padding: 16px 16px 14px;\n  }\n  .card .label {\n    font-size: 11px;\n    text-transform: uppercase;\n    letter-spacing: 0.06em;\n    color: var(--text-faint);\n    margin-bottom: 8px;\n  }\n  .card .value {\n    font-size: 24px;\n    font-weight: 650;\n    letter-spacing: -0.01em;\n    line-height: 1.2;\n    white-space: nowrap;\n  }\n  .card .value .unit {\n    font-size: 13px;\n    font-weight: 500;\n    color: var(--text-dim);\n    margin-left: 4px;\n  }\n  .card .sub {\n    font-size: 12px;\n    color: var(--text-faint);\n    margin-top: 6px;\n  }\n  .card.accent .value { color: var(--accent); }\n\n  .stability-bar-track {\n    height: 6px;\n    border-radius: 4px;\n    background: var(--surface-2);\n    overflow: hidden;\n    margin-top: 10px;\n  }\n  .stability-bar-fill {\n    height: 100%;\n    border-radius: 4px;\n    background: var(--ok);\n    transition: width 0.4s ease;\n  }\n\n  .panel {\n    background: var(--surface);\n    border: 1px solid var(--border);\n    border-radius: 10px;\n    padding: 18px;\n    margin-bottom: 16px;\n  }\n  .panel h2 {\n    font-size: 13px;\n    font-weight: 650;\n    text-transform: uppercase;\n    letter-spacing: 0.05em;\n    color: var(--text-dim);\n    margin: 0 0 14px;\n  }\n\n  .chart-wrap { overflow-x: auto; }\n  canvas#chart { display: block; width: 100%; height: 120px; }\n\n  table {\n    width: 100%;\n    border-collapse: collapse;\n    font-size: 13px;\n  }\n  th, td {\n    text-align: left;\n    padding: 7px 10px;\n    border-bottom: 1px solid var(--border);\n  }\n  th {\n    color: var(--text-faint);\n    font-weight: 600;\n    font-size: 11px;\n    text-transform: uppercase;\n    letter-spacing: 0.05em;\n  }\n  td.num { text-align: right; }\n  .badge {\n    display: inline-block;\n    padding: 1px 8px;\n    border-radius: 5px;\n    font-size: 12px;\n    font-weight: 650;\n  }\n  .badge.ok { background: var(--ok-dim); color: var(--ok); }\n  .badge.warn { background: var(--warn-dim); color: var(--warn); }\n  .badge.crit { background: var(--crit-dim); color: var(--crit); }\n\n  .empty-state {\n    text-align: center;\n    padding: 60px 20px;\n    color: var(--text-faint);\n  }\n  .empty-state .big {\n    font-size: 15px;\n    color: var(--text-dim);\n    margin-bottom: 6px;\n  }\n\n  footer {\n    text-align: center;\n    font-size: 11.5px;\n    color: var(--text-faint);\n    margin-top: 28px;\n  }\n</style>\n\n<div class=\"wrap\">\n  <header>\n    <div class=\"title-block\">\n      <h1>Sync monitor</h1>\n      <div class=\"sub\">okfish-pricing-engine · živé zatížení Shoptet API</div>\n    </div>\n    <div class=\"status-pill\" id=\"statusPill\">\n      <span class=\"status-dot\"></span>\n      <span id=\"statusText\">načítám…</span>\n    </div>\n  </header>\n\n  <div class=\"meta-row\" id=\"metaRow\"></div>\n\n  <div id=\"content\">\n    <div class=\"empty-state\">\n      <div class=\"big\">Zatím žádná data</div>\n      Čeká se na první odpověď z Workeru…\n    </div>\n  </div>\n\n  <footer>Aktualizuje se každé 3 s · zdroj: <span class=\"mono\">shoptet-vip-worker.hlancaric.workers.dev/v1/sync-stats</span></footer>\n</div>\n\n<script>\n  const WORKER_URL = '/v1/sync-stats';\n  const history = []; // {t, stabilityPct}\n  const MAX_HISTORY = 80;\n\n  function fmt(n) {\n    return new Intl.NumberFormat('cs-CZ').format(n || 0).replace(/\\s/g, '\\u00A0');\n  }\n\n  function statusBadgeForCode(code) {\n    const n = Number(code);\n    if (n >= 200 && n < 300) return 'ok';\n    if (n === 429) return 'warn';\n    if (n >= 400) return 'crit';\n    return 'warn';\n  }\n\n  function render(data) {\n    const pill = document.getElementById('statusPill');\n    const statusText = document.getElementById('statusText');\n    const meta = document.getElementById('metaRow');\n    const content = document.getElementById('content');\n\n    if (!data || data.status === 'idle') {\n      pill.className = 'status-pill';\n      statusText.textContent = 'nečinné';\n      meta.innerHTML = '';\n      content.innerHTML = '<div class=\"empty-state\"><div class=\"big\">Žádný sync neběží</div>' + (data && data.message ? data.message : 'Zatím žádný záznam.') + '</div>';\n      return;\n    }\n\n    const isRunning = data.running === true;\n    const isError = data.phase === 'error';\n    pill.className = 'status-pill ' + (isRunning ? 'running' : isError ? 'error' : 'done');\n    statusText.textContent = isRunning ? 'běží — ' + (data.phase || 'running') : isError ? 'chyba' : 'dokončeno';\n\n    const req = data.requests || { GET: 0, PATCH: 0 };\n    const rate = data.requestRatePerSec || { GET: 0, PATCH: 0 };\n    const stability = data.stabilityPct != null ? data.stabilityPct : 100;\n    const totalRetries = Object.values(data.retries || {}).reduce((a, b) => a + b, 0);\n    const totalReq = req.GET + req.PATCH;\n\n    meta.innerHTML =\n      '<span><b>' + (data.elapsedSeconds != null ? fmt(data.elapsedSeconds) + 's' : '—') + '</b> uplynulo</span>' +\n      '<span>naposledy: <b>' + (data.updatedAt ? new Date(data.updatedAt).toLocaleTimeString('cs-CZ') : '—') + '</b></span>' +\n      '<span>celkem retry: <b class=\"mono\">' + fmt(totalRetries) + '</b></span>';\n\n    if (isRunning || totalReq > 0) {\n      history.push({ t: Date.now(), stability });\n      if (history.length > MAX_HISTORY) history.shift();\n    }\n\n    const stabColor = stability >= 98 ? 'var(--ok)' : stability >= 85 ? 'var(--warn)' : 'var(--crit)';\n\n    let html = '<div class=\"grid\">';\n    html += cardBlock('GET požadavky', fmt(req.GET), rate.GET != null ? rate.GET.toFixed(1) + ' /s' : null);\n    html += cardBlock('PATCH požadavky', fmt(req.PATCH), rate.PATCH != null ? rate.PATCH.toFixed(1) + ' /s' : null);\n    html +=\n      '<div class=\"card\"><div class=\"label\">Stabilita</div>' +\n      '<div class=\"value\" style=\"color:' + stabColor + '\">' + stability.toFixed(1) + '<span class=\"unit\">% OK</span></div>' +\n      '<div class=\"stability-bar-track\"><div class=\"stability-bar-fill\" style=\"width:' + stability + '%; background:' + stabColor + '\"></div></div>' +\n      '</div>';\n    html += cardBlock('Retry pokusy', fmt(totalRetries), totalRetries > 0 ? 'viz tabulka níže' : 'bez problémů');\n    html += '</div>';\n\n    html += '<div class=\"panel\"><h2>Stabilita v čase</h2><div class=\"chart-wrap\"><canvas id=\"chart\" width=\"900\" height=\"120\"></canvas></div></div>';\n\n    const statuses = Object.entries(data.httpResponses || {});\n    if (statuses.length > 0) {\n      html += '<div class=\"panel\"><h2>HTTP odpovědi</h2><table><thead><tr><th>Status</th><th class=\"num\">Počet</th><th class=\"num\">Retry</th></tr></thead><tbody>';\n      statuses.sort((a, b) => Number(a[0]) - Number(b[0])).forEach(([code, count]) => {\n        const retryCount = (data.retries || {})[code] || 0;\n        html +=\n          '<tr><td><span class=\"badge ' + statusBadgeForCode(code) + ' mono\">' + code + '</span></td>' +\n          '<td class=\"num mono\">' + fmt(count) + '</td>' +\n          '<td class=\"num mono\">' + (retryCount > 0 ? fmt(retryCount) : '—') + '</td></tr>';\n      });\n      html += '</tbody></table></div>';\n    }\n\n    content.innerHTML = html;\n    drawChart();\n  }\n\n  function cardBlock(label, value, sub) {\n    return '<div class=\"card\"><div class=\"label\">' + label + '</div><div class=\"value mono\">' + value + '</div>' +\n      (sub ? '<div class=\"sub mono\">' + sub + '</div>' : '') + '</div>';\n  }\n\n  function drawChart() {\n    const canvas = document.getElementById('chart');\n    if (!canvas) return;\n    const ctx = canvas.getContext('2d');\n    const dpr = window.devicePixelRatio || 1;\n    const w = canvas.clientWidth, h = canvas.clientHeight;\n    canvas.width = w * dpr;\n    canvas.height = h * dpr;\n    ctx.scale(dpr, dpr);\n    ctx.clearRect(0, 0, w, h);\n\n    const styles = getComputedStyle(document.documentElement);\n    const border = styles.getPropertyValue('--border').trim();\n    const ok = styles.getPropertyValue('--ok').trim();\n\n    // grid\n    ctx.strokeStyle = border;\n    ctx.lineWidth = 1;\n    [0, 0.5, 1].forEach((f) => {\n      const y = h - f * (h - 10) - 5;\n      ctx.beginPath();\n      ctx.moveTo(0, y);\n      ctx.lineTo(w, y);\n      ctx.stroke();\n    });\n\n    if (history.length < 2) return;\n\n    const pts = history.map((d, i) => ({\n      x: (i / (MAX_HISTORY - 1)) * w,\n      y: h - (d.stability / 100) * (h - 10) - 5,\n    }));\n\n    // area fill\n    const grad = ctx.createLinearGradient(0, 0, 0, h);\n    grad.addColorStop(0, 'color-mix(in srgb, ' + ok + ' 28%, transparent)');\n    grad.addColorStop(1, 'color-mix(in srgb, ' + ok + ' 0%, transparent)');\n    ctx.beginPath();\n    ctx.moveTo(pts[0].x, h);\n    pts.forEach((p) => ctx.lineTo(p.x, p.y));\n    ctx.lineTo(pts[pts.length - 1].x, h);\n    ctx.closePath();\n    ctx.fillStyle = grad;\n    ctx.fill();\n\n    // line\n    ctx.beginPath();\n    pts.forEach((p, i) => (i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y)));\n    ctx.strokeStyle = ok;\n    ctx.lineWidth = 2;\n    ctx.lineJoin = 'round';\n    ctx.stroke();\n\n    // endpoint dot\n    const last = pts[pts.length - 1];\n    ctx.beginPath();\n    ctx.arc(last.x, last.y, 3.5, 0, Math.PI * 2);\n    ctx.fillStyle = ok;\n    ctx.fill();\n  }\n\n  async function poll() {\n    try {\n      const res = await fetch(WORKER_URL, { cache: 'no-store' });\n      const data = await res.json();\n      render(data);\n    } catch (e) {\n      document.getElementById('statusText').textContent = 'chyba spojení';\n    }\n  }\n\n  poll();\n  setInterval(poll, 3000);\n  window.addEventListener('resize', drawChart);\n</script>\n";
